    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 changeFee) public {
        address baseToken = address(0);
        address nft = address(1);
        uint128 virtualBase = 100;
        uint128 virtualNft = 200;
        uint16 feeRate = 100;
        bytes32 merkleRoot = bytes32(0);
        bool useOracle = false;
        bool payRoyalties = false;

        c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useOracle, payRoyalties);
        assertTrue(c.changeFee() == changeFee);
    }
}
